function validate([nums, target]) {
  if (nums.length < 1 || nums.length > 50000) return 'nums needs 1 to 5 * 10^4 values.';
  if (target.length < 1 || target.length > 4) return 'target needs 1 to 4 values.';
  if (target.length > nums.length) return 'target cannot be longer than nums.';
  if (nums.some(v => v < 1 || v > 10000) || target.some(v => v < 1 || v > 10000)) return 'Every value is between 1 and 10^4.';
  return null;
}

