function minimumIncrements(nums, target) {
  const m = target.length;
  const full = (1 << m) - 1;
  const gcd = (a, b) => {
    while (b !== 0) {
      [a, b] = [b, a % b];
    }
    return a;
  };

  const lcm = new Array(full + 1).fill(1);
  for (let sub = 1; sub <= full; sub++) {
    let value = 1;
    for (let j = 0; j < m; j++) {
      if (sub & (1 << j)) {
        value = value / gcd(value, target[j]) * target[j];
      }
    }
    lcm[sub] = value;
  }

  let dp = new Array(full + 1).fill(Infinity);
  dp[0] = 0;
  for (const num of nums) {
    const next = dp.slice();
    for (let sub = 1; sub <= full; sub++) {
      const cost = Math.ceil(num / lcm[sub]) * lcm[sub] - num;
      for (let mask = 0; mask <= full; mask++) {
        const total = dp[mask] + cost;
        if (total < next[mask | sub]) {
          next[mask | sub] = total;
        }
      }
    }
    dp = next;
  }
  return dp[full];
}

