function minimumIncrements(nums, target) {
  // Try every way to hand each target to one element of nums. An element must then reach the
  // smallest value at or above it that every target handed to it divides.
  const n = nums.length, m = target.length;
  const gcd = (a, b) => (b === 0 ? a : gcd(b, a % b));
  const owner = new Array(m).fill(0);
  let best = Infinity;
  for (;;) {
    let total = 0;
    for (let i = 0; i < n; i++) {
      let step = 1;
      for (let j = 0; j < m; j++) if (owner[j] === i) step = step / gcd(step, target[j]) * target[j];
      let value = nums[i];
      const rest = value % step;
      if (rest !== 0) value += step - rest;
      total += value - nums[i];
    }
    if (total < best) best = total;
    let j = 0;
    while (j < m && owner[j] === n - 1) owner[j++] = 0;
    if (j === m) break;
    owner[j]++;
  }
  return best;
}

