function generate(rand, size) {
  const pick = (low, high) => low + Math.floor(rand() * (high - low + 1));
  if (size === 'large') {
    // Either values anywhere in range, or small numbers and large targets built from one base so that some divide others.
    const spread = rand() < 0.5;
    const base = pick(300, 2500);
    const target = Array.from({ length: 4 }, () => (spread ? pick(1, 10000) : base * pick(1, 4)));
    const nums = Array.from({ length: 2000 }, () => (spread ? pick(1, 10000) : pick(1, 300)));
    return [nums, target];
  }
  const m = pick(1, 4);
  const n = pick(m, Math.min(8, m + 4));
  // Mostly small values so that targets share factors; sometimes the full range.
  const top = rand() < 0.15 ? 10000 : pick(4, 30);
  const nums = Array.from({ length: n }, () => pick(1, top));
  const target = Array.from({ length: m }, () => pick(1, top));
  return [nums, target];
}
